// Runs once per active Live Content record.
// slot = the ERPNext record for THIS item (paired via Split Out Slots).
// feed = the odds feed response for THIS item (from Get Odds Feed).
const slot = $('Split Out Slots').item.json;
const feed = $json;
const templates = $('Get Live Content Templates').first().json.data || [];

const TEAMS = {
  'Arizona Cardinals': 'ARI', 'Atlanta Falcons': 'ATL', 'Baltimore Ravens': 'BAL', 'Buffalo Bills': 'BUF',
  'Carolina Panthers': 'CAR', 'Chicago Bears': 'CHI', 'Cincinnati Bengals': 'CIN', 'Cleveland Browns': 'CLE',
  'Dallas Cowboys': 'DAL', 'Denver Broncos': 'DEN', 'Detroit Lions': 'DET', 'Green Bay Packers': 'GB',
  'Houston Texans': 'HOU', 'Indianapolis Colts': 'IND', 'Jacksonville Jaguars': 'JAX', 'Kansas City Chiefs': 'KC',
  'Las Vegas Raiders': 'LV', 'Los Angeles Chargers': 'LAC', 'Los Angeles Rams': 'LAR', 'Miami Dolphins': 'MIA',
  'Minnesota Vikings': 'MIN', 'New England Patriots': 'NE', 'New Orleans Saints': 'NO', 'New York Giants': 'NYG',
  'New York Jets': 'NYJ', 'Philadelphia Eagles': 'PHI', 'Pittsburgh Steelers': 'PIT', 'San Francisco 49ers': 'SF',
  'Seattle Seahawks': 'SEA', 'Tampa Bay Buccaneers': 'TB', 'Tennessee Titans': 'TEN', 'Washington Commanders': 'WAS',
};

if (!slot.event_id) {
  return { json: { ...slot, skip: true, skipReason: 'No Event ID set on this slot' } };
}

const tpl = templates.find((t) => t.name === slot.template);
if (!tpl || !tpl.url) {
  return { json: { ...slot, skip: true, skipReason: `No render URL found for template "${slot.template}"` } };
}

const game = (feed.events || []).find((e) => String(e.id) === String(slot.event_id));
if (!game) {
  return { json: { ...slot, skip: true, skipReason: `Event ${slot.event_id} not found in feed (may have started or expired)` } };
}

const slug = String(slot.uri || '').replace(/^\/+|\/+$/g, '');
if (!slug) {
  return { json: { ...slot, skip: true, skipReason: 'No URI (slug) set on this slot' } };
}
const base = $('Global Config').first().json.ftpBasePath.replace(/\/+$/, '');
const ftpPath = `${base}/${slug}.png`;
const publicUrlBase = $('Global Config').first().json.publicUrlBase.replace(/\/+$/, '');
const publicImageUrl = `${publicUrlBase}${ftpPath}`;

const away = game.competitors.find((c) => !c.home);
const home = game.competitors.find((c) => c.home);
const abbr = (c) => TEAMS[c.description] || c.description;
const market = (code) => game.markets.find((m) => m.code === code && m.status === 'OPEN');
const byTeam = (m, c) => m?.outcomes.find((o) => o.competitorId === c.id);
const byName = (m, n) => m?.outcomes.find((o) => o.description === n);
const line = (h) => { const n = Number(h); return n === 0 ? 'PK' : (n > 0 ? '+' : '') + n; };
const price = (o) => o.price.american;

const sp = market('2W-HCAP'), ml = market('2W-12'), tot = market('2W-OU');
const [spA, spH] = [byTeam(sp, away), byTeam(sp, home)];
const [mlA, mlH] = [byTeam(ml, away), byTeam(ml, home)];
const [ov, un] = [byName(tot, 'Over'), byName(tot, 'Under')];

const tz = 'America/New_York';
const fmtET = (d) => {
  const p = Object.fromEntries(new Intl.DateTimeFormat('en-US', { timeZone: tz, weekday: 'short', hour: 'numeric', minute: '2-digit', hour12: true }).formatToParts(new Date(d)).map((x) => [x.type, x.value]));
  return `${p.weekday} ${p.hour}:${p.minute} ${p.dayPeriod} ET`;
};

// Stable fields feed the change-detection hash. OddsAsOf is excluded on
// purpose — it's always "now", so including it would mark every run as
// changed and defeat the skip-if-unchanged check below.
const stableVars = {
  League: slot.league || '',
  Time: fmtET(game.startTime),
  Team1: away.description,
  Team2: home.description,
  Spread: spA && spH ? `Spread: ${abbr(away)} ${line(spA.price.handicap)} (${price(spA)}) | ${abbr(home)} ${line(spH.price.handicap)} (${price(spH)})` : '',
  MoneyLine: mlA && mlH ? `Moneyline: ${abbr(away)} ${price(mlA)} | ${abbr(home)} ${price(mlH)}` : '',
  Total: ov && un ? `Total: O ${Number(ov.price.handicap)} (${price(ov)}) | U ${Number(un.price.handicap)} (${price(un)})` : '',
};
const vars = { ...stableVars, OddsAsOf: fmtET(new Date()) };

const qs = Object.entries(vars).map(([k, v]) => `${k}=${encodeURIComponent(v)}`).join('&');
const cleanTemplateUrl = String(tpl.url).replace(/["']/g, '').split('?')[0];
const signature = JSON.stringify({ id: game.id, ...stableVars });

if (signature === slot.last_hash) {
  return { json: { ...slot, skip: true, skipReason: 'No change since last upload' } };
}

return { json: {
  ...slot,
  skip: false,
  eventId: game.id,
  matchup: `${away.description} @ ${home.description}`,
  ...vars,
  imageUrl: `${cleanTemplateUrl}?${qs}`,
  ftpPath,
  publicImageUrl,
  signature,
} };

const src = $('Select Featured Game For Slot').item.json;
const result = $json;
const uploadFailed = result.error !== undefined;
const out = {
  slotName: src.name,
  status: uploadFailed ? 'Error' : 'Success',
  errorMessage: uploadFailed ? String(result.error?.message || result.error) : '',
};
// Only touch eventId/signature/imageUrl on a real success — on error, leave
// ERPNext's existing values alone rather than overwriting with unknowns.
if (!uploadFailed) {
  out.eventId = src.eventId;
  out.signature = src.signature;
  out.imageUrl = src.publicImageUrl;
}
return { json: out };

// Nothing changed (or nothing to render) — report the skip but don't
// touch eventId/signature/imageUrl, so ERPNext keeps its last-known-good values.
const d = $json;
return { json: {
  slotName: d.name,
  status: 'Skipped',
  errorMessage: d.skipReason || '',
} };

